def solve_v3(input_grid):
    """
    Rule: Sort by (height - width) descending, then by max_row ascending for ties
    Place component i at (i * i, i) - triangular spacing
    Adjust dimensions: if width > 1, keep height else reduce height by 1
    """
    visited = set()
    h_in, w_in = len(input_grid), len(input_grid[0])

    def bfs(r, c, color):
        comp = [(r, c)]
        visited.add((r, c))
        stack = [(r, c)]
        while stack:
            cr, cc = stack.pop()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = cr+dr, cc+dc
                if 0 <= nr < h_in and 0 <= nc < w_in:
                    if input_grid[nr][nc] == color and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        comp.append((nr, nc))
                        stack.append((nr, nc))
        return comp

    comps = []
    for r in range(h_in):
        for c in range(w_in):
            color = input_grid[r][c]
            if color != 0 and (r, c) not in visited:
                comp = bfs(r, c, color)
                min_r, min_c = min(comp)
                max_r, max_c = max(comp)
                comps.append({
                    'color': color,
                    'min_row': min_r, 'max_row': max_r,
                    'height': max_r - min_r + 1,
                    'width': max_c - min_c + 1
                })

    # Sort by (height - width) desc, then max_row asc
    comps.sort(key=lambda x: (-x['height'] + x['width'], x['max_row']))

    out_h = len(comps) + 10
    out_w = len(comps) + 10
    out = [[0]*out_w for _ in range(out_h)]

    for idx, comp in enumerate(comps):
        if comp['width'] > 1:
            new_h = comp['height']
            new_w = max(1, comp['width'] - 1)
        else:
            new_h = max(1, comp['height'] - 1)
            new_w = 1

        # Try placing at (idx*something, idx)
        for base in range(5):
            start_r, start_c = idx * base, idx
            end_r = start_r + new_h
            end_c = start_c + new_w

            # Check if this placement overlaps with existing
            overlaps = False
            for r2 in range(len(out)):
                for c2 in range(len(out[0])):
                    if out[r2][c2] > 0:
                        if start_r <= r2 < end_r and start_c <= c2 < end_c:
                            if out[r2][c2] != comp['color']:
                                overlaps = True
                                break
                if overlaps: break
            if not overlaps:
                for r in range(start_r, end_r):
                    for c in range(start_c, end_c):
                        out[r][c] = comp['color']
                print(f"Placed color {comp['color']} at ({start_r},{start_c})")
                break

    return out[:out_h][:]

